// Cloudflare Worker entrypoint: the OpenNext-generated Next.js handler plus a
// Cron Trigger handler. The cron handler only calls the app's own
// /api/cron/daily route over the self-reference service binding, so all job
// logic lives in Next.js code with normal env access, logging and tests.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(controller, env, ctx) {
    ctx.waitUntil(
      (async () => {
        if (!env.WORKER_SELF_REFERENCE || !env.CRON_SECRET) {
          throw new Error("daily cron: WORKER_SELF_REFERENCE binding or CRON_SECRET missing");
        }
        const res = await env.WORKER_SELF_REFERENCE.fetch(
          "https://kavach.internal/api/cron/daily",
          {
            method: "POST",
            headers: {
              authorization: `Bearer ${env.CRON_SECRET}`,
              "x-cron": controller.cron,
            },
          },
        );
        if (!res.ok) {
          throw new Error(`daily cron failed: ${res.status} ${await res.text()}`);
        }
      })(),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
